package br.edu.ifc.treinoecapacitacao.view;
import br.edu.ifc.treinoecapacitacao.App; import br.edu.ifc.treinoecapacitacao.model.*; import javafx.geometry.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public class TelaParticipacoes { private Stage stage; public TelaParticipacoes(Stage stage){this.stage=stage;} public Scene criarCena(){ Label titulo=new Label("Participações");titulo.setId("tituloTreinamentos");ListView<Treinamento> treinos=new ListView<Treinamento>(App.treinamentos);treinos.setPrefHeight(130);ListView<Bombeiro> bombeiros=new ListView<Bombeiro>(App.bombeiros);bombeiros.setPrefHeight(130);ListView<Participacao> participacoes=new ListView<Participacao>(App.participacoes);participacoes.setPrefHeight(160);RadioButton inscrito=new RadioButton("Inscrito"),concluido=new RadioButton("Concluído"),reprovado=new RadioButton("Reprovado");ToggleGroup g=new ToggleGroup();inscrito.setToggleGroup(g);concluido.setToggleGroup(g);reprovado.setToggleGroup(g);inscrito.setSelected(true);Spinner<Integer> freq=new Spinner<Integer>(0,100,0,5);Spinner<Integer> nota=new Spinner<Integer>(0,10,0,1);GridPane dados=new GridPane();dados.setHgap(10);dados.setVgap(8);dados.getStyleClass().add("formulario");dados.add(new Label("Status:"),0,0);dados.add(new HBox(8,inscrito,concluido,reprovado),1,0);dados.add(new Label("Frequência:"),0,1);dados.add(freq,1,1);dados.add(new Label("Nota:"),0,2);dados.add(nota,1,2);Button associar=new Button("Associar participante");associar.getStyleClass().add("botao-principal");Button atualizar=new Button("Atualizar participação");Button voltar=new Button("Voltar"); associar.setOnAction(e->{Treinamento t=treinos.getSelectionModel().getSelectedItem();Bombeiro b=bombeiros.getSelectionModel().getSelectedItem();if(t==null||b==null){new Alert(Alert.AlertType.WARNING,"Selecione treinamento e bombeiro.").show();return;}if(!b.getStatus().equals("Ativo")){new Alert(Alert.AlertType.WARNING,"Apenas bombeiros ativos podem participar.").show();return;}for(Participacao p:App.participacoes)if(p.getTreinamento()==t&&p.getBombeiro()==b){new Alert(Alert.AlertType.WARNING,"Bombeiro já está neste treinamento.").show();return;}String st=concluido.isSelected()?"Concluído":reprovado.isSelected()?"Reprovado":"Inscrito";Participacao p=new Participacao(b,t,st,freq.getValue(),nota.getValue());App.participacoes.add(p);App.historico.add("Participação registrada: "+b.getNome()+" / "+t.getNome());}); atualizar.setOnAction(e->{Participacao p=participacoes.getSelectionModel().getSelectedItem();if(p==null){new Alert(Alert.AlertType.WARNING,"Selecione uma participação.").show();return;}String st=concluido.isSelected()?"Concluído":reprovado.isSelected()?"Reprovado":"Inscrito";p.setStatus(st);p.setFrequencia(freq.getValue());p.setNota(nota.getValue());participacoes.refresh();App.historico.add("Participação atualizada: "+p.getBombeiro().getNome());});voltar.setOnAction(e->{stage.setScene(new TelaDashboard(stage).criarCena());stage.setTitle("Painel - Treinamento e Capacitação");});VBox raiz=new VBox(10,titulo,new Label("Selecione o treinamento"),treinos,new Label("Selecione o bombeiro"),bombeiros,dados,new HBox(8,associar,atualizar,voltar),new Label("Participações registradas"),participacoes);raiz.setPadding(new Insets(18));Scene scene=new Scene(raiz,850,780);scene.getStylesheets().add("/css/style.css");return scene;} }
